def clap_error(message: str, usage: str = None, tip: str = None):
    err(f"error: {message}\n")
    if tip:
        err("\n")
        err(f"  tip: {tip}\n")
    if usage:
        err("\n")
        err(f"Usage: {usage}\n")
    err("\n")
    err("For more information, try '--help'.\n")
    return 2


def unexpected_arg(arg, usage, tip_pass=False, similar=None):
    tip = None
    if similar:
        tip = f"a similar argument exists: '{similar}'"
    elif tip_pass:
        tip = f"to pass '{arg}' as a value, use '-- {arg}'"
    return clap_error(f"unexpected argument '{arg}' found", usage, tip)


def unrecognized_subcommand(cmd, usage, similar=None):
    tip = f"a similar subcommand exists: '{similar}'" if similar else None
    return clap_error(f"unrecognized subcommand '{cmd}'", usage, tip)


def root_usage():
    return f"{bin_name()} [OPTIONS] [COMMAND]"


def check_usage():
    return f"{bin_name()} check [OPTIONS] [path]"


def clean_usage():
    return f"{bin_name()} clean"


def toolchain_usage():
    return f"{bin_name()} toolchain [COMMAND]"


def toolchain_install_usage():
    return f"{bin_name()} toolchain install [OPTIONS]"


def completions_usage():
    return f"{bin_name()} completions <SHELL>"


def has_help_flag(args):
    for a in args:
        if a == "--help" or a == "-h":
            return "long" if a == "--help" else "short"
        if a.startswith("-") and not a.startswith("--") and "h" in a[1:]:
            return "short"
    return None


def parse_short_group(token):
    # Return set of seen valid flags and first invalid rendered like clap usually does.
    flags = []
    for ch in token[1:]:
        if ch in ("h", "V", "q"):
            flags.append(ch)
        else:
            return flags, "-" + ch
    return flags, None


def home_runtime_dir(base_path=None):
    if base_path:
        return base_path
    return os.path.join(os.path.expanduser("~"), ".rustowl")


def sysroot_dir(base_path=None):
    return os.path.join(home_runtime_dir(base_path), "sysroot", TOOLCHAIN_DIRNAME)


def random_tmp_name():
    return ".tmp" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(6))


def install_toolchain(base_path=None, prefix_sysroot_missing=False):
    if prefix_sysroot_missing:
        log("INFO", "rustowl::toolchain", "sysroot not found; start setup toolchain")
    dest = sysroot_dir(base_path)
    try:
        os.makedirs(dest, exist_ok=True)
    except Exception:
        pass
    tmp = os.path.join(tempfile.gettempdir(), random_tmp_name())
    try:
        os.makedirs(tmp, exist_ok=True)
    except Exception:
        pass
    log("INFO", "rustowl::toolchain", "start installing Rust toolchain...")
    log("INFO", "rustowl::toolchain", f"temp dir is made: {tmp}")
    log("INFO", "rustowl::toolchain", f"start downloading {DOWNLOAD_URL}...")
    # The original proceeds to perform network I/O.  In this offline reimplementation
    # we stop after reproducing the visible setup/logging phase.
    return 1


