    # Match the visible order: toolchain setup/check happens before target validation.
    if not os.path.isdir(sysroot_dir()):
        return install_toolchain(prefix_sysroot_missing=True)
    log("WARN", "rustowl::toolchain", "cargo not found; fallback")
    log("WARN", "rustowl::toolchain", "rustowlc not found; fallback")
    target = path if path is not None else os.getcwd()
    if path is None:
        try:
            target = os.path.abspath(target)
        except Exception:
            pass
    if not (isinstance(target, str) and target.endswith(".rs")):
        log("WARN", "rustowl::lsp::analyze", f"Invalid analysis target: {target}")
        log("ERROR", "rustowl", "Analyze failed")
