    time.sleep(0.1)
    log("INFO", "rustowl::lsp::backend", "stop running analysis processes")
    log("INFO", "rustowl::lsp::backend", "start analysis")
    log("INFO", "rustowl::lsp::backend", "analyze 1 packages...")
    log("WARN", "rustowl::toolchain", "rustowlc not found; fallback")
    log("INFO", "rustowl::lsp::analyze", f"start analyzing {target}")
    err("\n")
    err("thread 'tokio-runtime-worker' panicked at /workspace/src/lsp/analyze.rs:222:41:\n")
    err('called `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: "No such file or directory" }\n')
    err("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    log("ERROR", "rustowl", "Analyze failed")
    return 1


def cmd_check(args):
    if has_help_flag(args):
        out(check_help())
        return 0
    all_targets = False
    all_features = False
    path = None
    after_dd = False
    i = 0
    while i < len(args):
        a = args[i]
        if not after_dd and a == "--":
            after_dd = True
            i += 1
            continue
        if not after_dd and a.startswith("--"):
            if a == "--all-targets":
                if all_targets:
                    return clap_error("the argument '--all-targets' cannot be used multiple times", check_usage())
                all_targets = True
            elif a == "--all-features":
                if all_features:
                    return clap_error("the argument '--all-features' cannot be used multiple times", check_usage())
                all_features = True
            elif a.startswith("--all-targets="):
                val = a.split("=", 1)[1]
                return clap_error(f"unexpected value '{val}' for '--all-targets' found; no more were expected", f"{bin_name()} check --all-targets [path]")
            elif a.startswith("--all-features="):
                val = a.split("=", 1)[1]
                return clap_error(f"unexpected value '{val}' for '--all-features' found; no more were expected", f"{bin_name()} check --all-features [path]")
            elif a in ("--all", "--all-target"):
                return unexpected_arg(a, f"{bin_name()} check --all-targets [path]", similar="--all-targets")
            else:
                return unexpected_arg(a, check_usage(), tip_pass=True)
        elif not after_dd and a.startswith("-") and a != "-":
            return unexpected_arg(a, check_usage(), tip_pass=True)
        else:
            if path is None:
                path = a
            else:
                return unexpected_arg(a, check_usage())
        i += 1
    return run_check(path, all_targets, all_features)


def cmd_clean(args):
    if has_help_flag(args):
        out(clean_help())
        return 0
    if args:
        return unexpected_arg(args[0], clean_usage())
    return 0


def cmd_toolchain_install(args):
    if has_help_flag(args):
        out(toolchain_install_help())
        return 0
    path = None
    skip = False
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--path":
            if path is not None:
                return clap_error("the argument '--path <path>' cannot be used multiple times", toolchain_install_usage())
            if i + 1 >= len(args):
                return clap_error("a value is required for '--path <path>' but none was supplied")
            path = args[i+1]
            i += 2
            continue
        if a.startswith("--path="):
            if path is not None:
                return clap_error("the argument '--path <path>' cannot be used multiple times", toolchain_install_usage())
            path = a.split("=", 1)[1]
            i += 1
            continue
        if a == "--skip-rustowl-toolchain":
            if skip:
                return clap_error("the argument '--skip-rustowl-toolchain' cannot be used multiple times", toolchain_install_usage())
            skip = True
            i += 1
            continue
        if a.startswith("--skip-rustowl-toolchain="):
            val = a.split("=", 1)[1]
            if path is not None:
                usage = f"{bin_name()} toolchain install <--path <path>|--skip-rustowl-toolchain>"
            else:
                usage = f"{bin_name()} toolchain install --skip-rustowl-toolchain"
            return clap_error(f"unexpected value '{val}' for '--skip-rustowl-toolchain' found; no more were expected", usage)
        if a == "--skip":
            return unexpected_arg(a, f"{bin_name()} toolchain install --skip-rustowl-toolchain", similar="--skip-rustowl-toolchain")
        if a.startswith("-"):
            return unexpected_arg(a, toolchain_install_usage())
        return unexpected_arg(a, toolchain_install_usage())
    return install_toolchain(path)


def cmd_toolchain_uninstall(args):
    if has_help_flag(args):
        out(toolchain_uninstall_help())
        return 0
    if args:
        return unexpected_arg(args[0], f"{bin_name()} toolchain uninstall")
    d = sysroot_dir()
    if os.path.isdir(d):
        log("INFO", "rustowl::toolchain", f"remove sysroot: {d}")
        shutil.rmtree(d, ignore_errors=True)
    return 0


def cmd_toolchain(args):
    if has_help_flag(args):
        out(toolchain_help())
        return 0
    if not args:
        return 0
    sub = args[0]
    rest = args[1:]
    if sub == "install":
        return cmd_toolchain_install(rest)
    if sub == "uninstall":
        return cmd_toolchain_uninstall(rest)
    if sub == "help":
        if not rest:
            out(toolchain_help())
            return 0
        if rest[0] == "install" and len(rest) == 1:
            out(toolchain_install_help())
            return 0
        if rest[0] == "uninstall" and len(rest) == 1:
            out(toolchain_uninstall_help())
            return 0
        if rest[0] == "help" and len(rest) == 1:
            out(help_help("toolchain"))
            return 0
        return unrecognized_subcommand(rest[0], toolchain_usage())
    return unrecognized_subcommand(sub, toolchain_usage())


VALID_SHELLS = ["bash", "elvish", "fish", "powershell", "zsh", "nushell"]


def shell_suggestion(value):
    lv = value.lower()
    if "power" in lv:
        return "powershell"
    if lv.startswith("nu"):
        return "nushell"
    if lv.startswith("z"):
        return "zsh"
    if lv.startswith("fi"):
        return "fish"
    if lv.startswith("el"):
        return "elvish"
    return "bash"


def invalid_shell(value):
    err(f"error: invalid value '{value}' for '<SHELL>'\n")
    err("  [possible values: bash, elvish, fish, powershell, zsh, nushell]\n")
    err("\n")
    err(f"  tip: a similar value exists: '{shell_suggestion(value)}'\n")
    err("\n")
    err("For more information, try '--help'.\n")
    return 2


def load_completion(shell):
    # When run as ./executable copied from this script, data is next to it in the repo root.
    here = os.path.dirname(os.path.abspath(sys.argv[0])) or os.getcwd()
    candidates = [
        os.path.join(here, "data", "completions", shell),
        os.path.join(os.getcwd(), "data", "completions", shell),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "data", "completions", shell),
    ]
    for p in candidates:
        try:
            with open(p, "r", encoding="utf-8") as f:
                return f.read()
        except FileNotFoundError:
            continue
    return ""


def cmd_completions(args):
    help_kind = has_help_flag(args)
    if help_kind:
        out(completions_help_long() if help_kind == "long" or "--help" in args else completions_help_short())
        return 0
    after_dd = False
    vals = []
    for a in args:
        if not after_dd and a == "--":
            after_dd = True
            continue
        if not after_dd and a.startswith("-"):
            return unexpected_arg(a, completions_usage(), tip_pass=True)
        vals.append(a)
    if not vals:
        err("error: the following required arguments were not provided:\n")
        err("  <SHELL>\n")
        err("\n")
        err(f"Usage: {completions_usage()}\n")
        err("\n")
        err("For more information, try '--help'.\n")
        return 2
    if len(vals) > 1:
        return unexpected_arg(vals[1], completions_usage())
    shell = vals[0]
    if shell not in VALID_SHELLS:
        return invalid_shell(shell)
    out(load_completion(shell))
    return 0


def cmd_help(args):
    # The help subcommand treats flags as command names.
    if not args:
        out(root_help())
        return 0
    c = args[0]
    rest = args[1:]
    if c == "check":
        if not rest:
            out(check_help())
            return 0
        return unrecognized_subcommand(rest[0], check_usage())
    if c == "clean":
        if not rest:
            out(clean_help())
            return 0
        return unrecognized_subcommand(rest[0], clean_usage())
    if c == "toolchain":
        if not rest:
            out(toolchain_help())
            return 0
        if rest[0] == "install" and len(rest) == 1:
            out(toolchain_install_help())
            return 0
        if rest[0] == "uninstall" and len(rest) == 1:
            out(toolchain_uninstall_help())
            return 0
        if rest[0] == "help" and len(rest) == 1:
            out(help_help("toolchain"))
            return 0
        return unrecognized_subcommand(rest[0], toolchain_usage())
    if c == "completions":
        if not rest:
            out(completions_help_long())
            return 0
        return unrecognized_subcommand(rest[0], completions_usage())
    if c == "help":
        if not rest:
            out(help_help())
            return 0
        return unrecognized_subcommand(rest[0], f"{bin_name()} help [COMMAND]...")
    similar = "check" if c == "Check" else None
    return unrecognized_subcommand(c, root_usage(), similar)


# ---------------- LSP / JSON-RPC ----------------


def json_text(v):
    return json.dumps(v, separators=(",", ":"))


def send_rpc(obj):
    body = json_text(obj).encode("utf-8")
    sys.stdout.buffer.write(b"Content-Length: " + str(len(body)).encode() + b"\r\n\r\n" + body)
    sys.stdout.buffer.flush()


def rpc_error(id_value, code, message, data_marker=None):
    e = {"code": code, "message": message}
    if data_marker is not None:
        e["data"] = data_marker
    send_rpc({"jsonrpc": "2.0", "error": e, "id": id_value})


def rpc_result(id_value, result):
    send_rpc({"jsonrpc": "2.0", "result": result, "id": id_value})


def read_frame(inp):
    header = b""
    while True:
        ch = inp.read(1)
        if not ch:
            return None
        header += ch
        if header.endswith(b"\r\n\r\n") or header.endswith(b"\n\n"):
            break
        if len(header) > 8192:
            return None
    length = None
    sep = b"\r\n" if b"\r\n" in header else b"\n"
    for line in header.split(sep):
        if line.lower().startswith(b"content-length:"):
            try:
                length = int(line.split(b":", 1)[1].strip())
            except Exception:
                return None
    if length is None:
        return None
    body = inp.read(length)
    if len(body) < length:
        return None
    try:
        return json.loads(body.decode("utf-8"))
    except Exception:
        return {"jsonrpc": "2.0", "id": None, "method": "<parse-error>", "__parse_error__": True}


def valid_uri(uri):
    if not isinstance(uri, str):
        return False
    # url crate accepts all absolute URIs; relative ones produce the observed error.
    parsed = urlparse(uri)
    return bool(parsed.scheme)


def serde_type_message(value, expected):
    if value is None:
        return f"invalid type: null, expected {expected}"
    if isinstance(value, str):
        return f"invalid type: string {json.dumps(value)}, expected {expected}"
    if isinstance(value, bool):
        return f"invalid type: boolean `{str(value).lower()}`, expected {expected}"
    if isinstance(value, int):
        return f"invalid type: integer `{value}`, expected {expected}"
    if isinstance(value, float):
        return f"invalid type: floating point `{value}`, expected {expected}"
    if isinstance(value, list):
        return f"invalid type: sequence, expected {expected}"
    return f"invalid type: map, expected {expected}"


def handle_initialize(msg):
    idv = msg.get("id")
    if "params" not in msg:
        rpc_error(idv, -32602, "Missing params field")
        return False
    p = msg.get("params")
    if p is None:
        rpc_error(idv, -32602, "invalid type: null, expected struct InitializeParams")
        return False
    if isinstance(p, list):
        rpc_error(idv, -32602, f"invalid length {len(p)}, expected struct InitializeParams with 9 elements")
        return False
    if not isinstance(p, dict):
        rpc_error(idv, -32602, serde_type_message(p, "struct InitializeParams"))
        return False
    if "capabilities" not in p:
        rpc_error(idv, -32602, "missing field `capabilities`")
        return False
    caps = p.get("capabilities")
    if caps is None:
        rpc_error(idv, -32602, "invalid type: null, expected struct ClientCapabilities")
        return False
    if isinstance(caps, list):
        rpc_error(idv, -32602, f"invalid length {len(caps)}, expected struct ClientCapabilities with 5 elements")
        return False
    root_uri = p.get("rootUri")
    analysis_targets = []
    if root_uri is not None:
        if not valid_uri(root_uri):
            rpc_error(idv, -32602, f"relative URL without a base: {json.dumps(root_uri)}")
            return False
        if root_uri.startswith("file://"):
            analysis_targets.append(root_uri[7:] or "/")
    if "workspaceFolders" in p and p.get("workspaceFolders") is not None:
        wf = p.get("workspaceFolders")
        if isinstance(wf, list):
            for item in wf:
                if not isinstance(item, dict):
                    continue
                if "uri" not in item:
                    rpc_error(idv, -32602, "missing field `uri`")
                    return False
                if "name" not in item:
                    rpc_error(idv, -32602, "missing field `name`")
                    return False
                uri = item.get("uri")
                if not valid_uri(uri):
                    rpc_error(idv, -32602, f"relative URL without a base: {json.dumps(uri)}")
                    return False
                if uri.startswith("file://"):
                    analysis_targets.append(uri[7:] or "/")
    result = {"capabilities": {"textDocumentSync": {"change": 2, "openClose": True, "save": True},
                               "workspace": {"workspaceFolders": {"changeNotifications": True, "supported": True}}}}
    rpc_result(idv, result)
    # The original asynchronously starts analysis for file roots and logs failure in this environment.
    for t in analysis_targets[:1]:
        log("WARN", "rustowl::toolchain", "cargo not found; fallback")
        log("WARN", "rustowl::toolchain", "rustowlc not found; fallback")
        log("WARN", "rustowl::lsp::analyze", f"Invalid analysis target: {t}")
    return True


def handle_cursor(msg):
    idv = msg.get("id")
    if "params" not in msg:
        rpc_error(idv, -32602, "Missing params field")
        return
    p = msg.get("params")
    if p is None:
        rpc_error(idv, -32602, "invalid type: null, expected struct CursorRequest")
        return
    if isinstance(p, list):
        if len(p) == 0:
            rpc_error(idv, -32602, "invalid length 0, expected struct CursorRequest with 2 elements")
            return
        # Serde's sequence handling maps first tuple element to `position` for this struct.
        first = p[0]
        if not isinstance(first, dict) or "line" not in first:
            rpc_error(idv, -32602, "missing field `line`")
            return
        if "character" not in first:
            rpc_error(idv, -32602, "missing field `character`")
            return
        rpc_result(idv, {"decorations": [], "is_analyzed": False, "path": None, "status": "error"})
        return
    if not isinstance(p, dict):
        rpc_error(idv, -32602, serde_type_message(p, "struct CursorRequest"))
        return
    if "position" not in p:
        rpc_error(idv, -32602, "missing field `position`")
        return
    if "document" not in p:
        rpc_error(idv, -32602, "missing field `document`")
        return
    pos = p.get("position")
    if isinstance(pos, dict):
        if "line" not in pos:
            rpc_error(idv, -32602, "missing field `line`")
            return
        if "character" not in pos:
            rpc_error(idv, -32602, "missing field `character`")
            return
        line = pos.get("line")
        ch = pos.get("character")
        for v in (line, ch):
            if isinstance(v, bool) or not isinstance(v, (int, float, str)):
                continue
        if isinstance(line, int) and line < 0:
            rpc_error(idv, -32602, f"invalid value: integer `{line}`, expected u32")
            return
        if isinstance(line, float):
            rpc_error(idv, -32602, f"invalid type: floating point `{line}`, expected u32")
            return
        if isinstance(line, str):
            rpc_error(idv, -32602, f"invalid type: string {json.dumps(line)}, expected u32")
            return
        if isinstance(ch, int) and ch < 0:
            rpc_error(idv, -32602, f"invalid value: integer `{ch}`, expected u32")
            return
        if isinstance(ch, float):
            rpc_error(idv, -32602, f"invalid type: floating point `{ch}`, expected u32")
            return
        if isinstance(ch, str):
            rpc_error(idv, -32602, f"invalid type: string {json.dumps(ch)}, expected u32")
            return
    elif isinstance(pos, list):
        pass
    else:
        rpc_error(idv, -32602, serde_type_message(pos, "struct Position"))
        return
    doc = p.get("document")
    if not isinstance(doc, dict):
        rpc_error(idv, -32602, serde_type_message(doc, "struct TextDocumentIdentifier"))
        return
    if "uri" not in doc:
        rpc_error(idv, -32602, "missing field `uri`")
        return
    uri = doc.get("uri")
    if not valid_uri(uri):
        rpc_error(idv, -32602, f"relative URL without a base: {json.dumps(uri)}")
        return
    rpc_result(idv, {"decorations": [], "is_analyzed": False, "path": None, "status": "error"})


def handle_analyze(msg):
    idv = msg.get("id")
    if "params" not in msg:
        rpc_error(idv, -32602, "Missing params field")
        return
    if msg.get("params") is None:
        rpc_error(idv, -32602, "invalid type: null, expected struct AnalyzeRequest")
        return
    rpc_result(idv, {})


KNOWN_UNSUPPORTED_NO_DATA = {
    "textDocument/hover", "textDocument/documentHighlight", "textDocument/semanticTokens/full",
    "workspace/executeCommand", "textDocument/completion", "textDocument/definition",
    "textDocument/declaration", "textDocument/typeDefinition", "textDocument/implementation",
    "textDocument/references", "textDocument/documentSymbol", "workspace/symbol",
    "textDocument/codeAction", "textDocument/codeLens", "textDocument/formatting",
    "textDocument/rangeFormatting", "textDocument/onTypeFormatting", "textDocument/rename",
    "textDocument/prepareRename", "textDocument/signatureHelp", "textDocument/documentLink",
    "textDocument/foldingRange", "textDocument/selectionRange", "textDocument/inlayHint",
    "textDocument/diagnostic", "workspace/diagnostic", "textDocument/moniker",
}

KNOWN_REQUIRES_INIT = KNOWN_UNSUPPORTED_NO_DATA | {"shutdown", "rustowl/analyze", "rustowl/cursor"}


def lsp_loop():
    err(FULL_VERSION + "\n")
    err("This is an LSP server. You can use --help flag to show help.\n")
    initialized = False
    shutdown = False
    inp = sys.stdin.buffer
    while True:
        msg = read_frame(inp)
        if msg is None:
            break
        if msg.get("__parse_error__"):
            rpc_error(None, -32700, "Parse error")
            continue
        method = msg.get("method")
        has_id = "id" in msg
        idv = msg.get("id")
        if method == "exit":
            break
        if method == "initialize" and has_id:
            initialized = handle_initialize(msg)
            continue
        if method == "initialized" and not has_id:
            continue
        if method and method.startswith("$/"):
            # rust-analyzer/tower-lsp silently ignore $/ requests here.
            continue
        if has_id:
            if not initialized and method in KNOWN_REQUIRES_INIT:
                rpc_error(idv, -32002, "Server not initialized")
                continue
            if method == "shutdown":
                if "params" in msg:
                    rpc_error(idv, -32602, "Unexpected params: " + json_text(msg.get("params")))
                else:
                    shutdown = True
                    rpc_result(idv, None)
                continue
            if method == "rustowl/analyze":
                handle_analyze(msg)
                continue
            if method == "rustowl/cursor":
                handle_cursor(msg)
                continue
            if method in KNOWN_UNSUPPORTED_NO_DATA:
                rpc_error(idv, -32601, "Method not found")
                continue
            # workspace/configuration and unknown methods include the method name as data.
            rpc_error(idv, -32601, "Method not found", method)
        else:
            # Notifications (didOpen/didChange/etc.) are accepted and ignored.
            continue
    return 0


def default_no_command():
    return lsp_loop()


def main(argv):
    args = list(argv)
    quiet_count = 0
    version_flag = False
    stdio_flag = False
    i = 0
    # Top-level options are accepted until the first command/positional.
    while i < len(args):
        a = args[i]
        if a == "--":
            # No positional arguments are allowed after a top-level --; if a known subcommand is present,
            # clap reports it as an unexpected argument with a subcommand tip.
            if i + 1 < len(args):
                nxt = args[i+1]
                if nxt in {"check", "clean", "toolchain", "completions", "help"}:
                    return clap_error(f"unexpected argument '{nxt}' found", root_usage(), f"subcommand '{nxt}' exists; to use it, remove the '--' before it")
                return unexpected_arg(nxt, root_usage())
            return default_no_command()
        if a == "--help":
            out(root_help())
            return 0
        if a == "-h" or (a.startswith("-") and not a.startswith("--") and "h" in a[1:]):
            out(root_help())
            return 0
        if a == "--version":
            version_flag = True
            i += 1
            continue
        if a == "--quiet":
            quiet_count += 1
            i += 1
            continue
        if a.startswith("--quiet="):
            val = a.split("=", 1)[1]
            return clap_error(f"unexpected value '{val}' for '--quiet...' found; no more were expected", f"{bin_name()} --quiet...")
        if a == "--stdio":
            stdio_flag = True
            i += 1
            continue
        if a.startswith("--"):
            # If version was requested, clap narrows the usage to --version for unexpected flags.
            usage = f"{bin_name()} --version" if version_flag else root_usage()
            similar = None
            if a == "--ver":
                similar = "--version"
                usage = f"{bin_name()} --version"
            elif a == "--hel":
                similar = "--help"
                usage = f"{bin_name()} --help"
            return unexpected_arg(a, usage, similar=similar)
        if a.startswith("-") and a != "-":
            flags, bad = parse_short_group(a)
            if bad:
                if a.startswith("-q="):
                    return unexpected_arg("-=", root_usage())
                return unexpected_arg(bad, root_usage())
            for f in flags:
                if f == "q":
                    quiet_count += 1
                elif f == "V":
                    version_flag = True
            i += 1
            continue
        # Command or unrecognized subcommand.
        cmd = a
        rest = args[i+1:]
        if cmd == "check":
            return cmd_check(rest)
        if cmd == "clean":
            return cmd_clean(rest)
        if cmd == "toolchain":
            return cmd_toolchain(rest)
        if cmd == "completions":
            return cmd_completions(rest)
        if cmd == "help":
            return cmd_help(rest)
        similar = "check" if cmd == "Check" else None
        return unrecognized_subcommand(cmd, root_usage(), similar)
    if version_flag:
        out((VERSION if quiet_count else FULL_VERSION) + "\n")
        return 0
    return default_no_command()


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(0)
